import{_ as i,H as p,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"16 | 打造个人产品（二）：GEO运营工具开发","description":"","frontmatter":{},"headers":[{"level":2,"title":"需求调研：值不值得做","slug":"需求调研-值不值得做","link":"#需求调研-值不值得做","children":[]},{"level":2,"title":"需求设计：应该做成什么样","slug":"需求设计-应该做成什么样","link":"#需求设计-应该做成什么样","children":[]},{"level":2,"title":"AI Coding：怎么做","slug":"ai-coding-怎么做","link":"#ai-coding-怎么做","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[]}],"relativePath":"AGI产品经理全栈进化指南/16｜打造个人产品（二）：GEO运营工具开发.md","filePath":"AGI产品经理全栈进化指南/16｜打造个人产品（二）：GEO运营工具开发.md","lastUpdated":1795450950000}'),a={name:"AGI产品经理全栈进化指南/16｜打造个人产品（二）：GEO运营工具开发.md"};function n(l,e,o,E,g,r){return p(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="_16-打造个人产品-二-geo运营工具开发" tabindex="-1">16 | 打造个人产品（二）：GEO运营工具开发 <a class="header-anchor" href="#_16-打造个人产品-二-geo运营工具开发" aria-label="Permalink to &quot;16 | 打造个人产品（二）：GEO运营工具开发&quot;">​</a></h1><p>你好，我是产品二姐。</p><p>上一讲，我们提到了个人开发者选产品方向时的三个原则：新赛道、快见效、自运营。这一讲，我们继续沿着这个标准，看另一个产品。</p><p>这个产品诉求来源于 GEO 这个新概念的普及，需求源自一位朋友的咨询。TA 在为一家传统制造业厂商做品牌运营时，发现即使作为头部生产制造商，当他开始使用豆包时，相关内容也不能很好地传递出专业回答，品牌传递效应非常弱。比如“xxx 品类该怎么选”，豆包的引用仍然是搜狐网这类 PC 互联网时期的信息。</p><p>在我深入调研后发现：虽然 GEO 见效不一定那么快，但是这个赛道足够长，国内新晋者尚未成熟，且朋友这边有丰富的客户资源，运营工作对我来说，也可以转交出去。满足新赛道、自运营两个条件，所以我决定用最小成本开始尝试。</p><p>在这一讲，我会详细讲述这个 AI 产品从零到一的诞生过程。大家应该还记得在第二章，我们也同样做过 AI 产品的从零到上线，不过当时的目的是希望你更快上手 vibe coding，是一次初体验。虽然这次同样是从零到一，但和第二章的初体验相比，是完成了对 AI 应用理解的全貌后，在全新平台上的新起点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/1.png" alt=""></a></p><p>你会看到一次精心策划的过程，包括：</p><ul><li><p>需求调研：从行业、用户诉求、竞品调研三个角度探讨这个需求值不值得做。</p></li><li><p>需求设计：从最小成本、最大效果的原则出发，设计第一版好用的 MVP 产品，让客户先用起来。</p></li><li><p>Coding 开发：从零开始，继续使用 Harness 理念，循序渐进逐步构建 MVP 产品。</p></li></ul><p>学完之后，你能初步理解，个人开发者如何起步做企业服务类产品。</p><p>接下来，就让我们开始吧。</p><h2 id="需求调研-值不值得做" tabindex="-1">需求调研：值不值得做 <a class="header-anchor" href="#需求调研-值不值得做" aria-label="Permalink to &quot;需求调研：值不值得做&quot;">​</a></h2><p>在需求调研中，首先要对行业有整体理解。</p><p>这个产品的赛道是 GEO，全称是 Generative Engine Optimization——生成式引擎优化，也就是通过内容运营，让豆包、DeepSeek 这类 AI 问答工具成为品牌的天然宣传渠道和流量入口。</p><p>与之对应的上一代类似赛道叫 SEO —— Search Engine Optimization，也就是通过丰富的内容营销，让搜索引擎成为品牌的天然流量。在国外，Google 是 SEO 的主要渠道，也就是所有的内容面向 Google 友好；而在国内，早期搜索引擎以百度为代表，后来逐渐被分到各个垂直App 里，比如淘天的商品搜索、小红书的生活攻略搜索等等，所以它被分化为面向搜索引擎、社交媒体、电商平台等不同的内容运营，很多时候不被称为 SEO，因此也不被国人熟悉。但这个赛道其实是长期伴随互联网发展而存在的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/2.png" alt=""></a></p><p>而 GEO 的出现，正在让内容营销有了新标准，新标准的定义则依赖于生成式引擎生成答案的原理。我们知道，AI 问答工具之所以能回答问题，背后经过了几个步骤：</p><ol><li><p>将用户的问题拆解为关键词；</p></li><li><p>用这些关键词搜索网页，得到 top N 的网页内容；</p></li><li><p>参考这些网页内容，综合给出答案；</p></li></ol><p>所以，品牌想通过 AI 问答工具触达用户，需要过三关：</p><ul><li><p>第一关：AI 搜索中，你的内容要排名靠前，比如进入前 50 名。这一点和 SEO 相似。</p></li><li><p>第二关：AI 回答中，要引用你的内容。用户更倾向于直接看答案，甚至不点引用源。所以GEO 不只是让内容贴近关键词，还要让内容贴近问题的答案。</p></li><li><p>第三关：AI 回答中，对你的品牌给出正面、专业的评价。到这一步，GEO 才真正产生品牌效果。</p></li></ul><p>这三关，每一关都要在前一关的基础上进行，层层递进。</p><p>新标准出现，就会带来新机会。参考 SEO 的发展路径，GEO 现在仍然处于早期探索阶段，并且未来也会长期伴随 AI 应用的普及。</p><p>看完行业所处阶段，接下来我们做竞品调研，一方面借鉴竞品优势，另一方面思考产品如何形成差异化。</p><p>我发现，国内大部分 GEO 工具并不开放，很多还停留在厂商内部的概念。大家都在摸索，远没有形成稳定格局。因此，这一轮竞品调研，我更关注功能借鉴，而不是市场占有率。我重点看了三个海外产品：Peec AI、TryProfound 和 Ranketta，你也可以打开这三个网站得出你的诉求。</p><ol><li>Peec AI</li></ol><p>Peec AI 重点追踪三个指标：</p><ul><li><p>Visibility：品牌有没有被提到；</p></li><li><p>Position：品牌在 AI 答案里的排序位置；</p></li><li><p>Sentiment：AI 对品牌的描述是正面还是负面。</p></li></ul><p>它还会让你配置 prompts、竞品品牌、国家，持续追踪品牌在不同 AI 平台上的表现。也就是说，Peec AI 会每天用固定 query 去问 ChatGPT 这类工具，再把品牌表现记录下来。</p><p>Peec AI 给我的启发是：GEO 工具的第一步，是先把问题可视化。比如它会把同一赛道里的不同品牌放在下面这样的四象限图里。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/3.png" alt=""></a></p><ol><li>TryProfound</li></ol><p>Profound 的定位不只是监测，而是覆盖完整链路：先发现用户在 AI 里问什么，再分析品牌和竞品如何出现，最后用 Agent 生产和优化内容。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/4.png" alt=""></a></p><p>Profound 给我的启发是：长期来看，GEO 不能只停留在 dashboard。客户最终要的不是一张漂亮报表，而是“我现在应该改哪篇文章、发到哪里、怎么证明它有效”。</p><p>所以，GEO 产品最终一定会走向 action loop，也就是从发现问题，到生成修复方案，再到验证效果。</p><ol><li>Ranketta</li></ol><p>Ranketta 没有做通用的品牌 SEO，而是把场景收窄到电商和 DTC 品牌，核心对象是商品和SKU。它追踪商品在 AI Search 和 AI Shopping 里的可见性，也会做商品目录 enrichment，比如标题、描述、属性、GTIN 等数据补全。</p><p>Ranketta 这种方式给我的启发是：对于传统电商代运营公司，这可以是新的衍生业务，但对我来说，并没有这个优势。</p><p>看完这三个产品之后，我确定了 GEO 服务的一个闭环流程：观察 &gt; 分析 &gt; 优化。</p><p>最后，我们再落脚到具体客户需求。</p><p>客户的诉求很直接：希望豆包、DeepSeek 在回答某类问题时，能推荐他的产品。沿着这个诉求往回推，有三件事要先想清楚：</p><ul><li><p>要让 AI 推荐他的产品，最好先让 AI 在回答时引用他的内容。</p></li><li><p>要让 AI 引用他的内容，就要知道 AI 喜欢引用什么样的内容。</p></li><li><p>要知道 AI 喜欢引用什么样的内容，就要先找到潜在买家会问什么问题。</p></li></ul><p>最终，需求点就出来了：</p><ul><li><p>找到潜在买家可能询问的问题。</p></li><li><p>分析 AI 经常引用什么内容。</p></li><li><p>在这些内容基础上，生成更好的答案。</p></li></ul><p>所以，第一版产品需要帮助用户分析问答引擎工具的喜好，并基于这些分析结论生产出更优内容，供客户采纳。至于长期持续的追踪，可以暂时由客户的运营小编人工观察变化。</p><p>这和刚刚从竞品里看到的闭环——观察 &gt; 分析 &gt; 优化——是一致的。</p><p>接下来要解决的问题就是：这个最小产品该怎么设计。</p><h2 id="需求设计-应该做成什么样" tabindex="-1">需求设计：应该做成什么样 <a class="header-anchor" href="#需求设计-应该做成什么样" aria-label="Permalink to &quot;需求设计：应该做成什么样&quot;">​</a></h2><p>对于这种绑定豆包 /DeepSeek 的工具，我选择了一个更轻的产品形态：浏览器插件。主要源于四个因素：</p><ol><li><p>豆包没有开放的 API。因此我们不能像调用普通接口一样拿到完整结果，而插件是在豆包网页端获得真实分析结果的最佳方式。</p></li><li><p>客户启动成本很低。插件之于互联网，有点像小程序之于微信生态。</p></li><li><p>初期开发工作量小，但后期一定可以成为客户的引流工具。就像 SEO 界的 AI TDK 插件一样。</p></li><li><p>客户能直观、真实地感受到分析结果。</p></li></ol><p>确定产品形态后，就可以开始着手产品设计了。这一步，我会产出两样东西：</p><p>一是 idea 文档。无需追求 PRD 的完整格式，而是先把产品骨架写清楚。在越早期，这些设计越需要你亲自把关，而不是依赖于 AI 完成。</p><p>二是使用 Google AI Studio 完成一个一个可交互的前端 Demo。</p><p>按照需求调研的思路，我把第一版用户旅程压缩成三步：发现、分析、仿写。</p><ul><li><p>发现，就是让用户看到：同一个提示词下，哪些网站容易被排在前面，哪些内容容易被 AI采纳。这里借鉴 Peec AI，采用四象限图来让用户直观感受到差异。</p></li><li><p>分析，就是让用户知道：这些内容为什么被采纳？是信源权重更高，还是表达方式更像 AI愿意引用的答案？也借鉴 Peec AI 的思路，使用高亮文字来展示引用内容与正负面评价。</p></li><li><p>仿写，就是把分析结果变成行动：学习好内容的结构，避开差内容的问题，产出一篇更有机会被 AI 采纳的新内容。这部分会通过设计精巧的提示词完成。</p></li></ul><p>我把上述内容大概写成了一个简单的 idea 文档。</p><p>接着，和第二章的起步方法一样，我采用 Google AI Studio 做 Demo，快速统一视觉、交互和信息架构。这里只需要把 idea 文档里的内容描述给 Google AI Studio 即可。按照我的经验，这里最好一次完成一个页面，逐步叠加，效果会更好。最终完成了三个核心页面的样板设计。</p><p>图一：发现。通过四象限发现高质量文章。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/5.png" alt=""></a></p><p>图二：分析。包括溯源分析（看文章哪些内容被引用了）和通用分析。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/6.png" alt=""></a></p><p>图三：仿写。锚定参考文章后输入品牌名称、特点进行仿写。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/7.png" alt=""></a></p><p>确定前端设计后，就可以把这个 Demo 的代码文件从 Google AI Studio 下载下来，得到Demo 文件。</p><p>这样，idea 草稿负责讲清楚“为什么做、做什么、怎么流转”，Demo 负责讲清楚“用户会看到什么、点哪里、怎么理解结果”, 完成这一步把关后，后面的事情可以多数交给 AI Coding 工具来完成。</p><h2 id="ai-coding-怎么做" tabindex="-1">AI Coding：怎么做 <a class="header-anchor" href="#ai-coding-怎么做" aria-label="Permalink to &quot;AI Coding：怎么做&quot;">​</a></h2><p>AI Coding 的第一步是为 Coding Agent 构建一个可长期、持续工作的环境，也就是 HarnessEngineering 的理念。你可以参考我的步骤依次完成。</p><p>第一步，写完整的 Spec 文档。</p><p>上一步我们先写了一份很粗的 Idea 草稿与 Demo，把它们交给 AI，让它和我一起细化需求。这里我使用的提示词很简单：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是一个新的项目，我在这里写了一个 Idea 草稿&lt;草稿文件&gt;、交互设计参考 &lt;​demo 文件&gt;，在正式开始开</span></span>
<span class="line"><span>&lt;​/demo 文件&gt;</span></span></code></pre></div><p>这一步完成后，我们拿到的就是一份完整的 PRD，PRD 整个目录如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/8.png" alt=""></a></p><p>第二步，UI/UX 设计标准。</p><p>UI/UX 设计标准主要是保证外观设计的统一、美观。我们可以根据前面的 Demo，也可以参考更多的设计，进行设计标准提取。</p><p>在这里和你分享一下我经常参考的设计网站：</p><ul><li><p>Dribbble：全球最大设计师聚合平台。</p></li><li><p>RecentDesign：更加前卫的优秀设计聚合站。</p></li><li><p>Mobbin：可以按照页面元素分类的设计聚合站。</p></li></ul><p>找到参考图之后，让 AI 从这些参考中提炼出一套简单标准，比如：配色体系用什么，按钮、圆角这类设计元素是什么风格等等。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请基于这个 Demo 和参考图，提炼一套 Chrome 插件的 UI/UX 设计标准，包括配色体系、logo 使用、按</span></span>
<span class="line"><span>这一步的产物，是一份 DESIGN_STANDARDS.md。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/9.png" alt=""></a></p><p>有了它之后，后面每次让 AI 改界面，都不是凭感觉改，而是按同一套标准改。这样产品不会越改越乱。</p><p>第三步，开发架构设计。</p><p>这一步的提示词也非常简单。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据 PRD 文档，生成具体的技术调研方案。</span></span></code></pre></div><p>生成的文档目录如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86%E5%85%A8%E6%A0%88%E8%BF%9B%E5%8C%96%E6%8C%87%E5%8D%97/images/16/10.png" alt=""></a></p><p>在这里，架构文档就是给 AI 画施工图。</p><p>第四步，项目管理。</p><p>这里我们继续沿用 Harness Engineering 的思路，先让 AI 给项目建立长期记忆，输入以下提示词：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是一个长期项目，务必做好项目进度追踪和管理。使用 harness skills 构建相应的文件，使这个项目能</span></span></code></pre></div><p>这一步生成了几类文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AGENTS.md：告诉后续 AI，这个项目是什么、目录怎么读、从哪里开始；</span></span>
<span class="line"><span>docs/：记录架构、设计标准、技术决策、质量要求、风险；</span></span>
<span class="line"><span>tasks.json：把开发任务拆成一条条可执行任务；</span></span>
<span class="line"><span>progress.md：每次完成后记录进度，方便下次接着做；</span></span>
<span class="line"><span>init.sh：新 session 开始时，用来快速恢复项目上下文。</span></span></code></pre></div><p>这几个文件看起来像“文档工作”，但本质上是让 AI 在长期任务中始终可回溯进度，不跑偏。</p><p>第五步才是真正开始 coding。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>到了这一步，才开始真正 Coding，我会让它按 tasks.json 里的任务，一个一个做。</span></span></code></pre></div><ul><li>好的，按照项目管理里的步骤，你来依次完成，先完成第一个任务，让我确认。</li></ul><p>比如第一步先做 Chrome 插件工程骨架，做完以后，不要急着进入下一步，而是先验收：</p><ul><li><p>能不能构建成功；</p></li><li><p>能不能在 Chrome 里加载；</p></li><li><p>side panel 能不能打开；</p></li></ul><p>确认没问题，再进入下一步，后面的开发也是这个节奏，这种节奏和我们在第 12 讲里的三步集成也是一样的思路。</p><p>这就是 AI Coding 里很重要的一点：让 Agent 像人类工程师一样，在迭代、反馈中逐步完成，而不是一次性生成。</p><p>第六步，做好版本管理。</p><p>当第一个 coding 任务完成后，就可以开始做代码版本管理，把项目提交到 Git 仓库，提示词也很简单：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>确认这个任务完成，请你保证任务进度已被记录。现在开始代码版本管理，把当前的代码提交到 GitHub。你知</span></span>
<span class="line"><span>并且每次完成任务后，我都会让 AI Coding 工具确认 progress.md 已经记录了本次进展。</span></span></code></pre></div><p>如此反复迭代上述的第五、六步，直到整个插件小产品完成。</p><p>在这里就不和你分享全部过程了，如果你觉得这个想法还不错，也想尝试，不妨在线下自己实践一下，并和我们分享。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>最后，我们来总结一下。</p><p>这节课，我们通过 GEO 运营插件这个工具，掌握了另外一类适合个人开发的产品——工具类产品。它与上一讲提到的内容聚合类产品，是适合个人开发者参与的两类产品，前者的内容天然自带运营优势，后者的插件形态小巧但有用，是用于试水 PMF 的好形式。</p><p>这个过程中，我们经历了三个阶段：</p><ul><li><p>需求调研阶段：主要判断它适不适合个人开发者切入。GEO 仍在早期，竞争格局很不稳定，且会长期伴随 AI 应用发展。所以它值得用最小成本试一试。这一步主要由人来完成。</p></li><li><p>需求设计阶段：我把第一版产品最终定为浏览器插件的形态，能低成本贴近真实场景，让客户先看到问题，再拿到可执行的内容优化方向。这一步也主要由人来完成。</p></li><li><p>AI Coding 阶段：首先为 Coding Agent 搭好环境，包括 PRD、设计标准、技术方案、项目管理、版本管理。只有把这些上下文固定下来，Agent 才能像一个长期合作的工程师一样，按任务逐步推进。</p></li></ul><p>至此，这一章我们的三个实战案例就完成了。在 11-14 讲，我们讲了基于 Hermes 框架构建垂直领域 Agent，适合职场同学参考并应用在自己的场景中；而 15、16 则更适合个人开发者。</p><p>下一节，我们就会再往前推一步，聊聊产品做出来之后，我们该如何思考商业化和增长。包括从商业出发如何切中用户需求，如何通过 GEO、SEO 让别人看到我们的产品，如何通过内容营销、高阶表达向客户推广、展示我们的产品。</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><p>你可以选择一个自己熟悉的平台，尝试设计一个“小而有用”的浏览器插件。比如：针对阿里巴巴做一个选品分析插件，帮商家快速看到某个品类下的热销商品、价格带和供应商特征；也可以针对 Boss 直聘做一个招聘需求洞察插件，帮求职者或培训机构观察某类岗位的高频技能、薪资区间和城市分布。</p><p>选好方向后，不要急着写代码，而是沿着这一讲的方法走一遍：</p><ul><li><p>这个插件服务谁？它嵌在哪个真实页面里？有没有什么竞品？</p></li><li><p>你可以先写一份简单 Idea 文档，再用 Google AI Studio 做出 1-3 个核心页面？</p></li><li><p>最后交给 AI Coding 工具生成 PRD、设计标准、技术方案和任务清单。</p></li></ul><p>注意不是一次做完整产品，而是把一个平台里的真实场景，变成一个能被 AI 持续开发的小产品起点。</p><p>欢迎你在留言区和我交流。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习。我们下节课见！</p>`,117)])])}const A=i(a,[["render",n]]);export{c as __pageData,A as default};
